// Generated by `just generate` from `src/plugins/claudetto-you-should-know/slices/notice/lab/notice.test.ts`. Edit the source and run `just generate`.
// Lab tests of the `notice` slice: the check of the first changing call of a turn, the band above the prompt, the heads-up note, and the calls that get no notice.
// The hooks sit above the stubs of the engine: the stubs answer the verdict, the model calls, and the clock, and record each toast.
// The band is drawn by `$.ui.mount`, and its state is read by `$.state.get`, as the plugin itself reads them.
// No model call goes out, and no Claude Code session runs.
// The gate, the run with no screen, and the claims about files have their own lab files.

import type {
  ModelCompleteResult,
  ModelForkResult,
  On,
  ToolCheckDecision,
} from "claude-code";
import { type Engine, expect, mock, test } from "claude-code/testing";

const PLUGIN = "claudetto-you-should-know";

const NO_USAGE = {
  input_tokens: 0,
  output_tokens: 0,
  cache_read_input_tokens: 0,
  cache_creation_input_tokens: 0,
};

const answered = (text: string) => ({
  isAnswered: true as const,
  text,
  usage: NO_USAGE,
});

/** A stable id for a test topic: ASCII words, as the prompt asks. */
const idOf = (topic: string): string =>
  `t-${[...topic].reduce((h, c) => (h * 31 + (c.codePointAt(0) ?? 0)) % 1000003, 7)}`;

/** An answer with a topic, in the object that the prompt asks for. */
const topicAnswer = (topic: string, id = idOf(topic)) =>
  answered(JSON.stringify({ topic, id, claims: [] }));

/** An answer with no topic. */
const NONE = answered('{"topic": null, "claims": []}');

const failed = (status: number) => ({
  isAnswered: false as const,
  reason: "api-error" as const,
  status,
  error: status === 429 ? ("rate_limit" as const) : ("server_error" as const),
  usage: NO_USAGE,
});

/** The world of one test: the answers of the model calls, in order, and the verdict of each call. */
type World = {
  readonly complete?: readonly ModelCompleteResult[];
  readonly fork?: readonly (ModelForkResult | "never")[];
  readonly decision?: ToolCheckDecision;
};

type Clock = ReturnType<typeof mock.clock>;

/** What the stubs saw: the prompts of each model call, each line in the debug log, and each text put in the prompt box. */
type Seen = {
  complete: string[];
  fork: string[];
  debug: string[];
  fills: string[];
};

/** Stubs for one test. The account has the flag on, and the session has a terminal. A model call past the end of its list gives no topic. */
const setup = (on: On, world: World = {}) => {
  const seen: Seen = { complete: [], fork: [], debug: [], fills: [] };
  const clock = mock.clock(on);
  mock.env(on, { HOME: "/home/u" });
  on("fs.read", () => ({
    value: '{"cachedGrowthBookFeatures":{"tengu_jolly_dewdrop":true}}',
  }));
  on("session.surfaces", () => ({ value: ["terminal"] }));
  on("session.start", (_$, e) => ({ cwd: e.cwd }));
  on("turn.start", (_$, e) => ({ turnId: e.turnId }));
  on("tool.check", () => ({ decision: world.decision ?? "allow" }));
  on("tool.call", () => ({ result: "ok", context: ["other"] }));
  // The bottom of the render chain: an empty box, so that a band the plugin does not draw shows nothing.
  on("ui.render", ($, e) => $.ui.resolve(e).Box({ children: [] }));
  on("model.complete", (_$, e) => {
    const reply = world.complete?.[seen.complete.length] ?? NONE;
    seen.complete.push(e.prompt);
    return { value: reply };
  });
  on("model.fork", (_$, e) => {
    const reply = world.fork?.[seen.fork.length] ?? NONE;
    seen.fork.push(e.prompt);
    return reply === "never" ? new Promise(() => {}) : { value: reply };
  });
  on("ui.log", (_$, e) => {
    if (e.to === "debug") seen.debug.push(e.text);
    return { value: undefined };
  });
  on("prompt.fill", (_$, e) => {
    seen.fills.push(e.text);
    return { isFilled: true };
  });
  return { seen, clock };
};

const ids = { last: 0 };

/**
 * One real call of `tool` with `input`, as the engine checks it, and then the model call that it starts runs to its end.
 * A query has no `tool_use_id`.
 */
const check = async (
  $: Engine,
  clock: Clock,
  tool: string,
  input: object,
  agentId?: string,
) => {
  const verdict = await $.tool.check({
    tool,
    input,
    tool_use_id: `toolu_${++ids.last}`,
    ...(agentId === undefined ? {} : { agentId }),
  });
  for (let i = 0; i < 5; i++) await clock.advance(0);
  return verdict;
};

const started = new WeakSet<Engine>();

/** Starts a turn, and the session before its first turn. */
const turn = async ($: Engine, text: string, turnId: string) => {
  if (!started.has($)) {
    started.add($);
    await $.session.start({ cwd: "/p", surface: null, isInteractive: true });
  }
  return $.turn.start({ text, turnId });
};

/** The band above the prompt, drawn as the terminal draws it. */
const mountBand = ($: Engine, hasSurvey = false) =>
  $.ui.mount({
    plugin: PLUGIN,
    surface: "terminal",
    component: "AbovePrompt",
    props: {
      hasSurvey,
      isWorking: false,
      maxRows: 20,
      bodyColumns: 80,
      scroll: { offset: 0, bodyRows: 20 },
      view: {},
    },
  });

/** A call of `Edit` through the chain of `tool.call`, with the note context that the plugin adds. */
const callEdit = ($: Engine, agentId?: string) =>
  $.tool.call({
    tool: "Edit",
    ...EDIT,
    ...(agentId === undefined ? {} : { agentId }),
  });

const EDIT = {
  file_path: "/p/src/retry.mjs",
  old_string: "3",
  new_string: "10",
};
const TOPIC =
  // biome-ignore lint/plugin: the topic is test input data
  "Ten tries with no delay can hit the rate limit of the API faster.";

/** True when the band above the prompt shows a topic. */
const shows = async ($: Engine) => {
  const band = await mountBand($);
  const found = await band.find({ type: "Text", text: /You should know/ });
  await band.unmount();
  return found !== undefined;
};

// biome-ignore lint/plugin: the test name is kept whole, because the `slice.ts` file references it
test("the first changing call of a turn shows the topic in the band", async ($: Engine, on: On) => {
  const { seen, clock } = setup(on, { complete: [topicAnswer(TOPIC)] });
  await turn($, "Raise the tries to 10.", "t1");
  expect((await check($, clock, "Edit", EDIT)).decision).toBe("allow");
  expect(seen.complete.length).toBe(1);
  expect(seen.complete[0]).toContain("Raise the tries to 10.");
  expect(seen.complete[0]).toContain("/p/src/retry.mjs");
  expect(seen.fork).toStrictEqual([]);
  const band = await mountBand($);
  const text = await band.find({ type: "Text", text: /You should know/ });
  expect(text).toBeDefined();
  // The text names the side check as the source, and not the user.
  expect(await band.find({ type: "Text", text: /side check/ })).toBeDefined();
  await band.unmount();
});

test("a read gets no check", async ($: Engine, on: On) => {
  const { seen, clock } = setup(on, { complete: [topicAnswer(TOPIC)] });
  await turn($, "Look at the file.", "t1");
  await check($, clock, "Bash", { command: "cat src/retry.mjs | head -5" });
  await check($, clock, "Bash", { command: "git log --oneline -3" });
  expect(seen.complete).toStrictEqual([]);
  expect(await shows($)).toBeFalsy();
});

test("a `Bash` call that changes something gets the check", async ($: Engine, on: On) => {
  const { seen, clock } = setup(on, { complete: [topicAnswer(TOPIC)] });
  await turn($, "Clean up.", "t1");
  await check($, clock, "Bash", { command: "cat a > b" });
  expect(seen.complete.length).toBe(1);
});

test("a turn with 5 edits makes one model call", async ($: Engine, on: On) => {
  const { seen, clock } = setup(on, { complete: [NONE, topicAnswer(TOPIC)] });
  await turn($, "Raise the tries.", "t1");
  for (const name of ["a", "b", "c", "d", "e"])
    await check($, clock, "Write", {
      file_path: `/p/${name}.txt`,
      content: name,
    });
  expect(seen.complete.length).toBe(1);
  expect(seen.fork).toStrictEqual([]);
});

// biome-ignore lint/plugin: the test name is kept whole, because the `slice.ts` file references it
test("two calls that are checked at the same time start one model call", async ($: Engine, on: On) => {
  const { seen, clock } = setup(on, { complete: [NONE, topicAnswer(TOPIC)] });
  await turn($, "Raise the tries.", "t1");
  await Promise.all([
    $.tool.check({ tool: "Edit", input: EDIT, tool_use_id: "toolu_p1" }),
    $.tool.check({
      tool: "Write",
      input: { file_path: "/p/b" },
      tool_use_id: "toolu_p2",
    }),
  ]);
  for (let i = 0; i < 5; i++) await clock.advance(0);
  expect(seen.complete.length).toBe(1);
});

test("the next turn gets its own check", async ($: Engine, on: On) => {
  const { seen, clock } = setup(on, { complete: [NONE, topicAnswer(TOPIC)] });
  await turn($, "Raise the tries.", "t1");
  await check($, clock, "Edit", EDIT);
  await turn($, "Now the delay.", "t2");
  await check($, clock, "Edit", EDIT);
  expect(seen.complete.length).toBe(2);
  expect(await shows($)).toBeTruthy();
});

