test("an HTTP 429 on the separate call ends the check, with no second call in the turn", async ($: Engine, on: On) => {
  const { seen, clock } = setup(on, {
    complete: [failed(429)],
    fork: [topicAnswer(TOPIC)],
  });
  await turn($, "Raise the tries.", "t1");
  await check($, clock, "Edit", EDIT);
  expect(seen.complete.length).toBe(1);
  expect(seen.fork).toStrictEqual([]);
  expect(await shows($)).toBeFalsy();
  expect(seen.debug.join("\n")).toContain("429");
});

test("after an HTTP 429, the next turns of the session use a fork", async ($: Engine, on: On) => {
  const { seen, clock } = setup(on, {
    complete: [failed(429)],
    fork: [NONE, topicAnswer(TOPIC)],
  });
  await turn($, "Raise the tries.", "t1");
  await check($, clock, "Edit", EDIT);
  await turn($, "Now the delay.", "t2");
  await check($, clock, "Edit", EDIT);
  await turn($, "And the jitter.", "t3");
  await check($, clock, "Edit", EDIT);
  expect(seen.complete.length).toBe(1);
  expect(seen.fork.length).toBe(2);
  expect(seen.fork[0]).toContain("/p/src/retry.mjs");
  expect(await shows($)).toBeTruthy();
});

test("a fork with nothing to fork shows no band", async ($: Engine, on: On) => {
  const nothing = {
    isAnswered: false as const,
    reason: "nothing-to-fork" as const,
    usage: NO_USAGE,
  };
  const { clock } = setup(on, { complete: [failed(429)], fork: [nothing] });
  await turn($, "Raise the tries.", "t1");
  await check($, clock, "Edit", EDIT);
  await turn($, "Now the delay.", "t2");
  expect((await check($, clock, "Edit", EDIT)).decision).toBe("allow");
  expect(await shows($)).toBeFalsy();
});

// biome-ignore lint/plugin: the test name is kept whole, because the `slice.ts` file references it
test("the tool does not wait for a fork that is slower than its bound", async ($: Engine, on: On) => {
  const { seen, clock } = setup(on, {
    complete: [failed(429)],
    fork: ["never"],
  });
  await turn($, "Raise the tries.", "t1");
  await check($, clock, "Edit", EDIT);
  await turn($, "Now the delay.", "t2");
  // No `clock.advance` before the verdict: the call of the tool must not wait for the fork.
  const verdict = await $.tool.check({
    tool: "Edit",
    input: EDIT,
    tool_use_id: "toolu_wait",
  });
  expect(verdict.decision).toBe("allow");
  await clock.advance(0);
  expect(seen.fork.length).toBe(1);
  await clock.advance(6000);
  expect(await shows($)).toBeFalsy();
});

