// biome-ignore lint/plugin: the test name is kept whole, because the `slice.ts` file references it
test("a topic with the id of a topic that showed is not shown again, whatever its words, and is sent as seen", async ($: Engine, on: On) => {
  const { seen, clock } = setup(on, {
    complete: [
      topicAnswer(TOPIC),
      topicAnswer("Inny tekst o tym samym.", idOf(TOPIC)),
    ],
  });
  await turn($, "Raise the tries.", "t1");
  await check($, clock, "Edit", EDIT);
  expect(await shows($)).toBeTruthy();
  await turn($, "Raise them more.", "t2");
  expect(await shows($)).toBeFalsy();
  await check($, clock, "Edit", EDIT);
  expect(seen.complete.length).toBe(2);
  expect(seen.complete[1]).toContain(TOPIC);
  expect(await shows($)).toBeFalsy();
});

test("a topic older than the seen bound still is not shown again", async ($: Engine, on: On) => {
  const topics = Array.from({ length: 12 }, (_, i) => `Topic ${i}.`);
  const { seen, clock } = setup(on, {
    complete: [
      ...topics.map((t) => topicAnswer(t)),
      topicAnswer(topics[0] ?? ""),
    ],
  });
  for (const i of topics.keys()) {
    await turn($, `Request ${i}.`, `t${i}`);
    await check($, clock, "Edit", EDIT);
  }
  await turn($, "Again.", "t-last");
  await check($, clock, "Edit", EDIT);
  expect(seen.complete.length).toBe(13);
  expect(seen.complete[12]).not.toContain("Topic 0.");
  expect(await shows($)).toBeFalsy();
});

