// biome-ignore lint/plugin: the test name is kept whole, because the `slice.ts` file references it
test("a heads-up stays in the session until the main agent reads it once", async ($: Engine, on: On) => {
  const { seen, clock } = setup(on, { complete: [topicAnswer(TOPIC)] });
  await turn($, "Raise the tries.", "t1");
  await check($, clock, "Edit", EDIT);
  const band = await mountBand($);
  await band.press({ key: "heads_up" });
  expect(seen.fills).toStrictEqual([`> ${TOPIC}\n`]);
  // A turn that ends with no tool call keeps the note for the next call.
  await turn($, "Now the delay.", "t2");
  const first = await callEdit($);
  expect(first.context).toStrictEqual([
    "other",
    expect.stringContaining(TOPIC),
  ]);
  // The note names the side check as the source, and does not say that the person wrote the topic.
  expect(first.context?.[1]).toContain("side check by a model");
  expect(first.context?.[1]).not.toContain("gave a heads-up");
  const second = await callEdit($);
  expect(second.context).toStrictEqual(["other"]);
});

// biome-ignore lint/plugin: the test name is kept whole, because the `slice.ts` file references it
test("a subagent's call takes no heads-up note, and the main agent's call does", async ($: Engine, on: On) => {
  const { clock } = setup(on, { complete: [topicAnswer(TOPIC)] });
  await turn($, "Raise the tries.", "t1");
  await check($, clock, "Edit", EDIT);
  await (await mountBand($)).press({ key: "heads_up" });
  expect((await callEdit($, "agent-1")).context).toStrictEqual(["other"]);
  expect((await callEdit($)).context).toStrictEqual([
    "other",
    expect.stringContaining(TOPIC),
  ]);
});

test("dismiss clears the band and writes no note", async ($: Engine, on: On) => {
  const { clock } = setup(on, { complete: [topicAnswer(TOPIC)] });
  await turn($, "Raise the tries.", "t1");
  await check($, clock, "Edit", EDIT);
  const band = await mountBand($);
  await band.press({ key: "dismiss" });
  expect(
    await band.find({ type: "Text", text: /You should know/ }),
  ).toBeUndefined();
  expect((await callEdit($)).context).toStrictEqual(["other"]);
});
